package ru.voicerooms;import java.net.URI;public final class TrustedOrigin {  public static final String BASE = "https://voise.24projects.ru";  public static final String TEST_ORIGIN = "http://10.0.2.2:5200";  public static java.util.Set<String> allowedOrigins() {    java.util.Set<String> origins = new java.util.HashSet<>();    origins.add(BASE);    if (BuildConfig.DEBUG) origins.add(TEST_ORIGIN);    return origins;  }  public static boolean isTrusted(String value) {    try {      URI u = new URI(value);      if (BuildConfig.DEBUG          && "http".equalsIgnoreCase(u.getScheme())          && "10.0.2.2".equals(u.getHost())          && u.getPort() == 5200          && u.getRawUserInfo() == null) return true;      return "https".equalsIgnoreCase(u.getScheme())          && "voise.24projects.ru".equalsIgnoreCase(u.getHost())          && (u.getPort() == -1 || u.getPort() == 443)          && u.getRawUserInfo() == null;    } catch (Exception e) {      return false;    }  }  private TrustedOrigin() {}}